from taf.sbts.oam.coam.admin.utils import raise_value_error


class ProceduresInterface21B(object):
    def enable_ethernet_port_security(self, timeout=60):
        """
        Enable ethernet port security.

        :param timeout: (optional) Time to wait for positive procedure result.

        :return: It returns value of status parameter.
        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-changeEthernetPortSecurity.html
        """
        return self._api_client.execute_procedure("changeEthernetPortSecurity",
                                                  {"enableEthernetPortSec": True}, timeout)

    def disable_ethernet_port_security(self, timeout=60):
        """
        Disable ethernet port security.

        :param timeout: (optional) Time to wait for positive procedure result.

        :return: It returns value of status parameter
        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-changeEthernetPortSecurity.html
        """
        return self._api_client.execute_procedure("changeEthernetPortSecurity",
                                                  {"enableEthernetPortSec": False}, timeout)

    def change_bts_rad_parameters(self, component, params, timeout=300):
        """
        Change RAD parameters.

        :param int component: BTS system component number
        :param string params: RAD parameters sting (parameter:value,...) eg. 210:5
        :param int timeout: Time to wait for positive procedure result.
        :return Union[str, dict]: Value of status parameter of BTS_SERVICE_PROCEDURE object

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-setRadParam.html
        """
        return self._change_rad_params("DynamicChanges", component, params, timeout)

    def change_bts_rad_parameters_permanently(self, component, params, timeout=300):
        """
        Change RAD parameters permanently.

        :param integer component: BTS system component number
        :param string params: RAD parameters sting (parameter:value,...) eg. 210:5
        :param int timeout: Time to wait for positive procedure result.
        :return Union[str, dict]: Value of status parameter of BTS_SERVICE_PROCEDURE object

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-setRadParam.html
        """
        return self._change_rad_params("PersistentChanges", component, params, timeout)

    def change_bts_rad_parameters_with_overreset(self, component, params, timeout=300):
        """
        Change RAD parameters persistent over one reset.

        :param integer component: BTS system component number
        :param string params: RAD parameters sting (parameter:value,...) eg. 210:5
        :param int timeout: Time to wait for positive procedure result.
        :return Union[str, dict]: Value of status parameter of BTS_SERVICE_PROCEDURE object

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-setRadParam.html
        """
        return self._change_rad_params("PersistentOverOneResetChanges", component, params, timeout)

    def reset_bts_rad_parameters(self, component, params, timeout=300):
        """
        Reset RAD parameters.

        :param integer component: BTS system component number
        :param string params: RAD parameters sting (parameter:value,...) eg. 210:5
        :param int timeout: Time to wait for positive procedure result.
        :return Union[str, dict]: Value of status parameter of BTS_SERVICE_PROCEDURE object

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-setRadParam.html
        """
        return self._change_rad_params("FactoryDefaults", component, params, timeout)

    def _change_rad_params(self, setting_type, component, params, timeout):
        changed_params = self._parse_rad_parameters(params)
        return self._api_client.execute_procedure("setRadParam",
                                                  {"btsSwSystemComponent": component, "radSettingType": setting_type,
                                                   "radParams": changed_params},
                                                  timeout)

    def _parse_rad_parameters(self, params):
        changed_params = []
        for param in params.split(","):
            if not param:
                continue
            index, value = param.split(":")
            changed_params.append({"paramIndexNumber": int(index), "paramValue": int(value)})
        return changed_params

    def set_ssh_access(self, enable, timeout=30):
        parameters = {'enable': enable}
        return self._api_client.execute_procedure("executeChangeSshAccessState", parameters=parameters, timeout=timeout)

    def change_rnd_port_security(self, enable=True, timeout=60):
        """
        Change power state for fuse in power module.

        :param bool enable: bool value to either enable or disable
        :param float timeout: Time to wait for positive procedure result.
        :return Union[str, dict]: value of status parameter of BTS_SERVICE_PROCEDURE object

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-executeChangeRndPortState.html
        """
        parameters = {'enable': enable}
        return self._api_client.execute_procedure("executeChangeRndPortState", parameters=parameters, timeout=timeout)

    def calibrate_epimc_fhs(self, dist_name, timeout=900):
        """
        Calibrates EPIMC function on AFAA FHS

        :param dist_name: FHS_R dist name
        :param float timeout: Time to wait for positive procedure result
        :return: list: List of calibration results.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-calibrateEPIMCFHS.html
        """
        parameters = {'distName': dist_name}
        return self._api_client.execute_procedure("calibrateEPIMCFHS", parameters=parameters, timeout=timeout)

    def set_rad_debug_parameters(self, domain, persistency, name, value, timeout=60, detailed_output=False):
        """
        Set R&D debug parameters

        [DEPRECATION WARNING] This keyword is deprecated. Use set_multiple_rad_debug_parameters instead.

        :param string domain: Domain.
        :param string persistency: One of <Persistent/OneReset/NotPersistent>.
        :param string name: Parameter name.
        :param string value: Parameter value.
        :param int timeout: Time in seconds to wait for positive procedure result.
        :param bool detailed_output: Return full request response when True, defaults set to False.
        :return dict: Procedure feedback.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-setRADDebugParameters.html
        """
        if persistency not in ["Persistent", "OneReset", "NotPersistent"]:
            raise_value_error(param="persistency",
                              value=str(persistency),
                              subpage="tutorial-setRADDebugParameters.html")

        parameters = {"domain": domain, "persistency": persistency,
                      "parameters": [{"name": name, "value": value}]}

        response = self._api_client.execute_customer_procedure("setRADDebugParameters", parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def set_multiple_rad_debug_parameters(self, domain, persistency, rad_parameters, timeout=60, detailed_output=False):
        """
        Set R&D debug parameters

        :param string domain: Domain.
        :param string persistency: One of <Persistent/OneReset/NotPersistent>.
        :param list rad_parameters: List of parameter dicts as following:
        {
                    "name": string, //mandatory
                    "value": string //mandatory
                }
        :param int timeout: Time in seconds to wait for positive procedure result.
        :param bool detailed_output: Return full request response when True, defaults set to False.
        :return dict: Procedure feedback.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-setRADDebugParameters.html
        """
        if persistency not in ["Persistent", "OneReset", "NotPersistent"]:
            raise_value_error(param="persistency",
                              value=str(persistency),
                              subpage="tutorial-setRADDebugParameters.html")

        parameters = {"domain": domain, "persistency": persistency,
                      "parameters": rad_parameters}

        response = self._api_client.execute_customer_procedure("setRADDebugParameters", parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def reset_rad_debug_parameters(self, domain, name, timeout=60, detailed_output=False):
        """
        Reset R&D debug parameters

        :param string domain: Domain.
        :param string name: Parameter name.
        :param int timeout: Time in seconds to wait for positive procedure result.
        :param bool detailed_output: Return full request response when True, defaults set to False.
        :return dict: Procedure feedback.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-resetRADDebugParameter.html
        """
        parameters = {"domain": domain, "name": name}

        response = self._api_client.execute_customer_procedure("resetRADDebugParameter", parameters, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def get_non_default_rad_debug(self, timeout=60, detailed_output=False):
        """
        Get non default rad debug.

        :param int timeout: Time in seconds to wait for positive procedure result.
        :param bool detailed_output: Return full request response when True, defaults set to False.
        :return dict: Procedure feedback.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getNonDefaultRADDebugParameters.html
        """
        response = self._api_client.execute_customer_procedure("getNonDefaultRADDebugParameters", {}, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)
